INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1165221-me411', 'stk-user6067', 'ME 411', 'info', '{"desc": "اتمنى الإجابه ممن أخذ هذا الكورس سابقا:\n\n1-البروجكت راح يبدا من هذا الكورس ولا هو مجرد مقدمه لـ me412 ,يعني بس مجرد لكتشر؟\n2- القروب اللي راح اعمل معاهم لازم من هذا الكورس نجتمع ولا كيف؟؟\n3- اقدر اخلي سمستر بين ال411 و 412 ولا لازم اخذهم ورا بعض ؟\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-411-senior-design-project-i/120749/2", "user": "user6067", "ts": 1358411617000, "tid": 120749, "pn": 2}}', 1358411617000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1165768-me411', 'stk-mechanical_boy', 'ME 411', 'info', '{"desc": "me411 في اول كلاس راح يقولكم الدكتور عن مكان الورقه الي عاده يعلقها على لوحه الاعلانات جنب اللاب في مبنى 22 المهم الورقه تضم اسماء الدكاتره الي راح ينزلون البروجكتات في الترم + وش نوع البروجكت + كم طالب يبيه الدكتور . لانه بعض الدكاتره يبي 2 والبعض 3 والبعض 4 وهكذا . انا انصحك انك تختار قروبك من الحين ونزلوا نفس الكلاس عشان اول لكتشر تقدر تختار الدكتور الي انت تبيه. بالنسبه للكورس انا اشوفه ممل هي عباره عن لكتشر في الاسبوع اهم شي هو انك تحضر لاتغيب لان القريد فيه هالكورس يعتمد على الحضور + تقييم الدكتور الي راح تشتغل معاه. والكورس عباره عن بحث عن البروجكت ودكتورك الي راح تختاره راح يسوي معاكم ميتنغ يشوف وش نتيجه الابحاث . اما في كورس me412 راح يكون فيه شغلكم وتجاربكم ولازم تسوون ريبورت بالاخير + برزنتيشن وهالكورس ماراح يكون فيه لكتشر اسبوعي بس ميتنغ مع دكتور البروجكت\n\nبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-411-senior-design-project-i/120749/4", "user": "Mechanical_Boy", "ts": 1358547712000, "tid": 120749, "pn": 4}}', 1358547712000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hamd00ni-me411', 'stk-hamd00ni', 'ME 411', 'doc', '{"docs": [{"id": "stk-dr-f118631", "n": "Dr. Jafar Al-Bin-Mousa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME411- Term 161\n\nالمادة ما كان فيها شيء بس يقلب في السلايدات ويعلق على بعض الاشياء لكن طريقته في الشرح عجبتني كثير والكلاس كان جدا ممتع وكنت أتحمس للحضور\n\nدكتور باين عليه ممتاز في الشرح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467272-me411", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jafar-al-bin-mousa/118631/24", "user": "Hamd00ni", "ts": 1485767778000, "tid": 118631, "pn": 24}}]}', 1485767778000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
